  "cookieCenter.fact.consent.body": "Consent-related browser state helps us respect prior trust choices.",
  "cookieCenter.fact.consent.title": "Consent records",
  "cookieCenter.fact.control.body": "Browser settings and privacy flows give you meaningful control over cookie behavior.",
