  "securityCenter.hero.meta.updated": "Last updated: March 20, 2026",
  "securityCenter.hero.subtitle": "This page turns platform security, reliability, incident readiness, and trust controls into a readable product-grade security experience.",
  "securityCenter.hero.title": "Security posture that users can understand before they trust us with work.",
  "securityCenter.hero.version": "Version 2026.2",
  "securityCenter.section.compliance.p1": "Our security posture connects to privacy, GDPR, account protection, and legal notice workflows so users are not forced to treat these as disconnected promises.",
  "securityCenter.section.compliance.p2": "This means public trust pages, privacy request actions, and policy update communications can reinforce one another instead of drifting apart over time.",
  "securityCenter.section.compliance.summary": "Security posture is strongest when privacy rights, legal transparency, and operational controls stay connected.",
  "securityCenter.section.compliance.title": "Compliance, privacy, and user controls",
  "securityCenter.section.encryption.p1": "We use layered controls such as transport encryption, at-rest protection, role-based access, session controls, and provider-backed authentication flows to reduce unauthorized access risk.",
  "securityCenter.section.encryption.p2": "Authentication and access policy are linked to account state, entitlement controls, and security workflows rather than isolated login-only logic.",
  "securityCenter.section.encryption.summary": "Core protections for credentials, sessions, transport, storage, and privileged access.",
  "securityCenter.section.encryption.title": "Encryption, authentication, and access control",
  "securityCenter.section.focus": "Pin section",
  "securityCenter.section.operations.b1": "Operational monitoring and alerting support early issue detection",
  "securityCenter.section.operations.b2": "Incident workflows support containment, recovery, and review",
  "securityCenter.section.operations.b3": "Security and privacy surfaces remain linked for user trust continuity",
  "securityCenter.section.operations.p1": "Monitoring, alerting, performance checks, route-health controls, and audit visibility all contribute to our security posture. Security is linked to reliability because silent product failure is also a trust issue.",
  "securityCenter.section.operations.p2": "When incidents happen, we aim for documented response, operational containment, and transparent recovery practices rather than vague blanket assurances.",
  "securityCenter.section.operations.summary": "We use layered monitoring and operational response patterns to detect issues and recover quickly.",
  "securityCenter.section.operations.title": "Monitoring, incident response, and platform operations",
  "securityCenter.section.posture.b1": "Security posture is tied to identity, route access, plan state, and operational monitoring",
  "securityCenter.section.posture.b2": "Public trust signals remain connected to privacy and GDPR rights surfaces",
  "securityCenter.section.posture.b3": "Controls are intended to be legible to both individuals and compliance reviewers",
  "securityCenter.section.posture.p1": "RealAICoach is built for users and teams who need visible guardrails around access, billing, privacy, and operational trust. Security is treated as a product layer, not an afterthought hidden in vendor jargon.",
  "securityCenter.section.posture.p2": "Our public security page is designed to help users evaluate our approach before they become paid users, and to support lightweight due-diligence conversations without requiring an enterprise sales workflow first.",
  "securityCenter.section.posture.summary": "Explains how RealAICoach thinks about platform trust, resilience, access control, and operational defense.",
  "securityCenter.section.posture.title": "Security posture and platform model",
